#!/usr/bin/env python3
"""Generates testdata/fakes/<machine>: fs/ files and cmd/ outputs for piaccept --fake."""
import json, os, re, shutil
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "fakes")

def key(cmd): return re.sub(r"[/ ,]", "_", cmd)

def osrel(pretty, code):
    return f'PRETTY_NAME="{pretty}"\nNAME="Debian GNU/Linux"\nVERSION_CODENAME={code}\nID=debian\n'

BASE_FS = {
    "/proc/uptime": "93784.12 350000.00\n",
    "/proc/swaps": "Filename Type Size Used Priority\n",
    "/sys/class/net/wlan0/operstate": "up\n",
    "/dev/watchdog": "",
    "/etc/systemd/system.conf": "[Manager]\n",
}

def write(name, fs, cmd, sim):
    d = os.path.join(ROOT, name)
    shutil.rmtree(d, ignore_errors=True)
    for p, c in {**BASE_FS, **fs}.items():
        if c is None: continue
        f = os.path.join(d, "fs", p.lstrip("/"))
        os.makedirs(os.path.dirname(f), exist_ok=True)
        open(f, "w").write(c)
    os.makedirs(os.path.join(d, "cmd"), exist_ok=True)
    for c, out in cmd.items():
        open(os.path.join(d, "cmd", key(c) + ".txt"), "w").write(out)
    json.dump(sim, open(os.path.join(d, "sim.json"), "w"), indent=1)

def sim(n, t0, t1, mhz, throttle_at=None, flag=0x50005, drop=None):
    out = []
    for i in range(n):
        t = t0 + (t1 - t0) * (1 - (1 - i / (n - 1)) ** 2)
        thr = flag if throttle_at is not None and i >= throttle_at else 0
        m = drop if thr and drop else mhz
        out.append({"at": "2026-11-20T12:00:00Z", "temp_c": round(t, 1), "arm_mhz": m, "throttled": thr})
    return out

ping_ok = "5 packets transmitted, 5 received, 0% packet loss, time 820ms\nrtt min/avg/max/mdev = 0.412/0.634/0.981/0.190 ms\n"

# ── pi5-good: clean Pi 5 8 GB, NVMe-less SD, Bookworm 64-bit ─────────────
